def solve(coins, amount):
    # Edge case: amount zero requires zero coins
    if amount == 0:
        return 0
    # Initialize DP array with a large value (amount+1 is safe as max coins needed)
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        min_coins = INF
        for c in coins:
            if c <= a:
                # candidate using this coin
                cand = dp[a - c] + 1
                if cand < min_coins:
                    min_coins = cand
        dp[a] = min_coins
    return dp[amount] if dp[amount] != INF else -1

