def solve(path: str) -> str:
    """Simplify a Unix-style path.
    Handles both absolute and relative paths robustly.
    - Resolves '.' and '..' components.
    - Collapses multiple slashes.
    - Removes trailing slash except for root.
    """
    # Determine if the original path is absolute
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components (caused by '//' or leading/trailing slash) and current dir
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                # At root for absolute paths, ignore; for relative paths, keep '..'
                if not is_abs:
                    stack.append('..')
        else:
            stack.append(part)
    if is_abs:
        # Absolute path: join with leading slash, root is '/' when stack empty
        return '/' + '/'.join(stack) if stack else '/'
    else:
        # Relative path: if empty, return '.' (current directory)
        return '/'.join(stack) if stack else '.'

def solve(n):
    """Return the count of prime numbers strictly less than n."""
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start)//step + 1)
