def solve(path: str) -> str:
    """Simplify a Unix-style path.
    Handles absolute and relative paths:
    - Resolves '.' and '..'
    - Collapses multiple slashes
    - Removes trailing slash (except root for absolute, or returns '.' for empty relative)
    """
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack: list[str] = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                if not is_abs:
                    # preserve leading '..' in relative paths
                    stack.append('..')
                # if absolute and stack empty, stay at root (ignore)
        else:
            stack.append(part)
    if is_abs:
        return '/' + '/'.join(stack) if stack else '/'
    else:
        # Relative path: if empty, represent current directory
        return '/'.join(stack) if stack else '.'

