def solve(s):
    """Return length of the longest substring without repeating characters.
    Handles any input by converting to string; treats None as empty.
    """
    if s is None:
        return 0
    s = str(s)
    left = 0
    seen = {}
    max_len = 0
    for right, ch in enumerate(s):
        # If character seen and its last index is within current window
        prev_index = seen.get(ch)
        if prev_index is not None and prev_index >= left:
            left = prev_index + 1
        seen[ch] = right
        cur_len = right - left + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

def solve(n):
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve[:n])

