from fractions import Fraction

def solve(mat):
    # mat is list of list of ints, square matrix
    n = len(mat)
    if n == 0:
        return 1  # determinant of 0x0 matrix is 1 by convention
    # copy to Fraction matrix
    a = [[Fraction(x) for x in row] for row in mat]
    det = Fraction(1)
    for i in range(n):
        # find pivot
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            det = -det
        det *= a[i][i]
        # eliminate below
        for j in range(i+1, n):
            factor = a[j][i] / a[i][i]
            for k in range(i, n):
                a[j][k] -= factor * a[i][k]
    # det is product of pivots
    # result should be integer
    return int(det)

