def solve(grid):
    """Count islands in a binary grid (0/1 values).
    Supports rectangular or jagged grids. Only cells exactly equal to 1 are land.
    Adjacent cells are up, down, left, right.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def neighbors(r, c):
        # Up
        if r - 1 >= 0 and c < len(grid[r - 1]):
            yield r - 1, c
        # Down
        if r + 1 < rows and c < len(grid[r + 1]):
            yield r + 1, c
        # Left
        if c - 1 >= 0:
            yield r, c - 1
        # Right
        if c + 1 < len(grid[r]):
            yield r, c + 1
    def dfs(sr, sc):
        stack = [(sr, sc)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] == 1:
                    stack.append((nr, nc))
    count = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and (r, c) not in visited:
                dfs(r, c)
                count += 1
    return count

